package recruiter

import (
	"context"
	"strings"
	"testing"

	"github.com/weitzer-org/job_tracker/internal/storage"
)

type gsrWitnessStorageClient struct {
	storage.Client
	cancel     context.CancelFunc
	writeCount int
}

func (m *gsrWitnessStorageClient) ReadFile(ctx context.Context, bucket, key string) ([]byte, string, error) {
	if err := ctx.Err(); err != nil {
		return nil, "", err
	}
	return []byte(`{}`), "etag1", nil
}

func (m *gsrWitnessStorageClient) WriteFile(ctx context.Context, bucket, key string, data []byte, ifMatch string) error {
	if err := ctx.Err(); err != nil {
		return err
	}
	m.writeCount++
	if m.cancel != nil {
		m.cancel()
	}
	return storage.ErrETagMismatch
}

func TestGSRWitness(t *testing.T) {
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	client := &gsrWitnessStorageClient{cancel: cancel}
	s := &Store{Storage: client, Bucket: "test-bucket"}

	_, err := s.Mutate(ctx, "https://linkedin.com/in/jane", func(c Contact) Contact {
		return c
	})

	if client.writeCount != 1 {
		t.Fatalf("Mutate(ctx, ...) called WriteFile %d times, want 1", client.writeCount)
	}
	if err == nil {
		t.Fatalf("expected an error, got nil")
	}
	// The correct behavior is returning the context cancellation error on the next iteration's ReadFile,
	// not exhausting the max write retries.
	if strings.Contains(err.Error(), "giving up") {
		t.Fatalf("Mutate(ctx, ...) returned %q, want context cancellation error", err)
	}
}

package recruiter

import (
	"context"
	"testing"

	"github.com/weitzer-org/job_tracker/internal/storage"
)

type gsrWitnessStorage struct {
	storage.Client
	writes int
	cancel context.CancelFunc
}

func (s *gsrWitnessStorage) ReadFile(ctx context.Context, bucket, key string) ([]byte, string, error) {
	if err := ctx.Err(); err != nil {
		return nil, "", err
	}
	return []byte(`{}`), "etag1", nil
}

func (s *gsrWitnessStorage) WriteFile(ctx context.Context, bucket, key string, data []byte, ifMatch string) error {
	if err := ctx.Err(); err != nil {
		return err
	}
	s.writes++
	s.cancel() // Cancel the context to simulate timeout/cancellation during this attempt
	return storage.ErrETagMismatch
}

func TestGSRWitness(t *testing.T) {
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	st := &gsrWitnessStorage{
		Client: storage.NewMemoryClient(),
		cancel: cancel,
	}
	store := &Store{Storage: st, Bucket: "test-bucket"}

	_, _ = store.Mutate(ctx, "https://linkedin.com/in/jane", func(c Contact) Contact { return c })

	// The claim states the loop "keeps sleeping and retrying until maxWriteRetries is exhausted"
	// even when the context is cancelled. A correct implementation will abort on the next read/write
	// because they honor the cancelled context, resulting in fewer writes than maxWriteRetries.
	if st.writes == maxWriteRetries {
		t.Fatalf("Mutate() retried %d times until exhaustion despite cancelled context, want loop to abort early", st.writes)
	}
}

package recruiter

import (
	"context"
	"errors"
	"testing"

	"github.com/weitzer-org/job_tracker/internal/storage"
)

type gsrWitnessStorage struct {
	storage.Client
	cancel context.CancelFunc
}

func (s *gsrWitnessStorage) ReadFile(ctx context.Context, bucket, key string) ([]byte, string, error) {
	if err := ctx.Err(); err != nil {
		return nil, "", err
	}
	return []byte(`{}`), "etag1", nil
}

func (s *gsrWitnessStorage) WriteFile(ctx context.Context, bucket, key string, data []byte, ifMatch string) error {
	if err := ctx.Err(); err != nil {
		return err
	}
	// Cancel the context during the first write conflict, simulating a timeout or cancellation exactly as it conflicts.
	s.cancel()
	return storage.ErrETagMismatch
}

func TestGSRWitness(t *testing.T) {
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	store := &Store{
		Storage: &gsrWitnessStorage{cancel: cancel},
		Bucket:  "test-bucket",
	}

	_, err := store.Mutate(ctx, "test-url", func(c Contact) Contact { return c })

	// The correct behavior is that the subsequent readAll call naturally propagates the context 
	// cancellation, thereby aborting the retry loop early instead of exhausting maxWriteRetries.
	if !errors.Is(err, context.Canceled) {
		t.Fatalf("Mutate() error = %v, want error wrapping context.Canceled", err)
	}
}
